INSERT INTO categories (name, description) VALUES ('Engine Components', 'Internal combustion engine parts, belts, water pumps, valves, and gaskets');
INSERT INTO categories (name, description) VALUES ('Transmission & Drivetrain', 'Clutch kits, gearboxes, CV joints, drive shafts, and fluids');
INSERT INTO categories (name, description) VALUES ('Brake System', 'Brake pads, discs, shoes, master cylinders, and brake fluids');
INSERT INTO categories (name, description) VALUES ('Suspension & Steering', 'Shock absorbers, tie rods, ball joints, sway bars, and rack ends');
INSERT INTO categories (name, description) VALUES ('Electrical & Electronic', 'Batteries, alternators, starters, spark plugs, sensors, and bulbs');
INSERT INTO categories (name, description) VALUES ('Filters & Air Intake', 'Oil filters, air filters, cabin/AC filters, and fuel filters');
INSERT INTO categories (name, description) VALUES ('Fluids & Lubricants', 'Engine oil, transmission fluid, coolant, power steering, and gear oil');
INSERT INTO categories (name, description) VALUES ('Exhaust & Emissions', 'Mufflers, catalytic converters, oxygen sensors, and exhaust gaskets');
INSERT INTO categories (name, description) VALUES ('Cooling System', 'Radiators, thermostats, coolant hoses, radiator caps, and fan assemblies');
INSERT INTO categories (name, description) VALUES ('Wheels & Tires', 'Tires, wheel bearings, valves, and balance weights');
INSERT INTO categories (name, description) VALUES ('Air Conditioning (AC)', 'AC compressors, condensers, evaporators, expansion valves, and freon');
INSERT INTO categories (name, description) VALUES ('Body, Glass & Accessories', 'Wiper blades, horn sets, mirrors, clips, and trim accessories');
